-- 跨域季度风险评分与经营报告
-- 原生MySQL 8.4未执行。先从第二部分资源导入对应隔离数据库。
-- 公开基准参考解；独立执行等价解，不得变动原库。
WITH qm AS (SELECT DISTINCT month_key,CONCAT(SUBSTR(month_key,1,4),'-Q',CASE WHEN SUBSTR(month_key,6,2)<='03' THEN '1' WHEN SUBSTR(month_key,6,2)<='06' THEN '2' WHEN SUBSTR(month_key,6,2)<='09' THEN '3' ELSE '4' END) q FROM calendar_days WHERE month_key>='2025-01'), qs AS (SELECT q,MAX(month_key) end_m FROM qm GROUP BY q), s AS (SELECT qm.q,SUM(v.net_cents) net,SUM(v.net_cents-v.cost_cents) gross FROM v_sales_lines v JOIN qm ON qm.month_key=SUBSTR(v.order_date,1,7) GROUP BY qm.q), f AS (SELECT qm.q,SUM(v.expense_cents) expense FROM v_expenses v JOIN qm ON qm.month_key=SUBSTR(v.entry_date,1,7) GROUP BY qm.q), h AS (SELECT qm.q,SUM(v.labor_cents) labor FROM v_staff_month v JOIN qm ON qm.month_key=v.month_key GROUP BY qm.q), p AS (SELECT qm.q,COUNT(*) n,SUM(CASE WHEN v.on_time>=v.quantity_ordered THEN 1 ELSE 0 END) good FROM v_po_lines v JOIN qm ON qm.month_key=SUBSTR(v.promised_date,1,7) GROUP BY qm.q), i AS (SELECT SUBSTR(snapshot_date,1,7) m,SUM(quantity*unit_cost_cents) stock FROM inventory_snapshots GROUP BY SUBSTR(snapshot_date,1,7)), z AS (SELECT qs.q,s.net,100.0*s.gross/NULLIF(s.net,0) margin,100.0*COALESCE(f.expense,0)/NULLIF(s.net,0) expense_pct,100.0*COALESCE(h.labor,0)/NULLIF(s.net,0) labor_pct,100.0*p.good/NULLIF(p.n,0) delivery,i.stock FROM qs LEFT JOIN s ON s.q=qs.q LEFT JOIN f ON f.q=qs.q LEFT JOIN h ON h.q=qs.q LEFT JOIN p ON p.q=qs.q LEFT JOIN i ON i.m=qs.end_m) SELECT q,net net_cents,ROUND(margin,2) margin_pct,ROUND(expense_pct,2) expense_pct,ROUND(labor_pct,2) labor_pct,ROUND(delivery,2) delivery_pct,stock stock_cents,CASE WHEN margin<30 THEN 1 ELSE 0 END+CASE WHEN expense_pct>50 THEN 1 ELSE 0 END+CASE WHEN labor_pct>20 THEN 1 ELSE 0 END+CASE WHEN delivery<60 THEN 1 ELSE 0 END risk_count,CASE WHEN margin IS NULL THEN 1 ELSE 0 END+CASE WHEN expense_pct IS NULL THEN 1 ELSE 0 END+CASE WHEN labor_pct IS NULL THEN 1 ELSE 0 END+CASE WHEN delivery IS NULL THEN 1 ELSE 0 END missing_count FROM z ORDER BY q;

-- 等价解（SQLite已验证，MySQL待复验）
WITH qm AS (SELECT DISTINCT month_key,CONCAT(SUBSTR(month_key,1,4),'-Q',CASE WHEN SUBSTR(month_key,6,2)<='03' THEN '1' WHEN SUBSTR(month_key,6,2)<='06' THEN '2' WHEN SUBSTR(month_key,6,2)<='09' THEN '3' ELSE '4' END) q FROM calendar_days WHERE month_key>='2025-01'), qs AS (SELECT q,MAX(month_key) end_m FROM qm GROUP BY q), s AS (SELECT qm.q,SUM(v.net_cents) net,SUM(v.net_cents-v.cost_cents) gross FROM v_sales_lines v JOIN qm ON qm.month_key=SUBSTR(v.order_date,1,7) GROUP BY qm.q), f AS (SELECT qm.q,SUM(v.expense_cents) expense FROM v_expenses v JOIN qm ON qm.month_key=SUBSTR(v.entry_date,1,7) GROUP BY qm.q), h AS (SELECT qm.q,SUM(v.labor_cents) labor FROM v_staff_month v JOIN qm ON qm.month_key=v.month_key GROUP BY qm.q), p AS (SELECT qm.q,COUNT(1) n,SUM(CASE WHEN v.on_time>=v.quantity_ordered THEN 1 ELSE 0 END) good FROM v_po_lines v JOIN qm ON qm.month_key=SUBSTR(v.promised_date,1,7) GROUP BY qm.q), i AS (SELECT SUBSTR(snapshot_date,1,7) m,SUM(quantity*unit_cost_cents) stock FROM inventory_snapshots GROUP BY SUBSTR(snapshot_date,1,7)), z AS (SELECT qs.q,s.net,100.0*s.gross/NULLIF(s.net,0) margin,100.0*COALESCE(f.expense,0)/NULLIF(s.net,0) expense_pct,100.0*COALESCE(h.labor,0)/NULLIF(s.net,0) labor_pct,100.0*p.good/NULLIF(p.n,0) delivery,i.stock FROM qs LEFT JOIN s ON s.q=qs.q LEFT JOIN f ON f.q=qs.q LEFT JOIN h ON h.q=qs.q LEFT JOIN p ON p.q=qs.q LEFT JOIN i ON i.m=qs.end_m) SELECT q,net net_cents,ROUND(margin,2) margin_pct,ROUND(expense_pct,2) expense_pct,ROUND(labor_pct,2) labor_pct,ROUND(delivery,2) delivery_pct,stock stock_cents,CASE WHEN margin<30 THEN 1 ELSE 0 END+CASE WHEN expense_pct>50 THEN 1 ELSE 0 END+CASE WHEN labor_pct>20 THEN 1 ELSE 0 END+CASE WHEN delivery<60 THEN 1 ELSE 0 END risk_count,CASE WHEN margin IS NULL THEN 1 ELSE 0 END+CASE WHEN expense_pct IS NULL THEN 1 ELSE 0 END+CASE WHEN labor_pct IS NULL THEN 1 ELSE 0 END+CASE WHEN delivery IS NULL THEN 1 ELSE 0 END missing_count FROM z ORDER BY q;
